-- DE-1B immutable whole-same whole relation; verified whole relation only; no accounting or VAT consumption. PostgreSQL 17 and trusted application schema.
BEGIN;
SELECT finance_assert_document_definitions(pg_catalog.current_schema());
-- Reviewed whole-set ledger. It records human review; it never posts or consumes a tax amount.
CREATE TABLE IF NOT EXISTS finance_group_fence (fence_id integer PRIMARY KEY CHECK(fence_id=1),version bigint NOT NULL);
INSERT INTO finance_group_fence VALUES(1,0) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS finance_group_cases (
 case_id text PRIMARY KEY,subject_id text NOT NULL,group_key text NOT NULL,created_request_id text NOT NULL UNIQUE,actor_user_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subject_id,group_key)
);
CREATE TABLE IF NOT EXISTS finance_group_requests (
 request_id text PRIMARY KEY,action text NOT NULL CHECK(action IN('evidence','verify','withdraw')),actor_user_id text NOT NULL,
 payload_json jsonb NOT NULL,payload_hash text NOT NULL CHECK(payload_hash=finance_document_hash(payload_json)),result_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS finance_group_evidence (
 manifest_id text PRIMARY KEY,subject_id text NOT NULL,document_id text NOT NULL,document_hash text NOT NULL,
 payload_json jsonb NOT NULL,manifest_hash text NOT NULL CHECK(manifest_hash=finance_document_hash(payload_json)),
 verification_level text NOT NULL CHECK(verification_level='human_review'),actor_user_id text NOT NULL,
 request_id text NOT NULL UNIQUE REFERENCES finance_group_requests(request_id) DEFERRABLE INITIALLY DEFERRED,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS finance_group_revisions (
 revision_id text PRIMARY KEY,case_id text NOT NULL REFERENCES finance_group_cases(case_id),version integer NOT NULL CHECK(version>0),
 previous_revision_id text UNIQUE REFERENCES finance_group_revisions(revision_id),schema_version text NOT NULL CHECK(schema_version='de1b-group-revision-v1'),
 state text NOT NULL CHECK(state IN('verified_group','withdrawn')),input_json jsonb NOT NULL,preview_json jsonb NOT NULL,basis_json jsonb NOT NULL,
 proof_hash text NOT NULL CHECK(proof_hash=finance_document_hash(jsonb_build_object('input',input_json,'preview',preview_json,'basis',basis_json))),
 withdrawal_reason text,request_id text NOT NULL UNIQUE REFERENCES finance_group_requests(request_id) DEFERRABLE INITIALLY DEFERRED,
 actor_user_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),apply_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(case_id,version),CHECK((version=1)=(previous_revision_id IS NULL)),CHECK((state='withdrawn')=(withdrawal_reason IS NOT NULL)),CHECK(withdrawal_reason IS NULL OR length(btrim(withdrawal_reason)) BETWEEN 1 AND 2000)
);
CREATE TABLE IF NOT EXISTS finance_group_members (
 revision_id text NOT NULL REFERENCES finance_group_revisions(revision_id),member_no integer NOT NULL CHECK(member_no>=0),
 role text NOT NULL CHECK(role IN('singleton','member')),document_id text NOT NULL,portion_id text NOT NULL,observation_id text NOT NULL,
 summary_json jsonb NOT NULL,PRIMARY KEY(revision_id,member_no),UNIQUE(revision_id,document_id),UNIQUE(revision_id,portion_id),CHECK((member_no=0)=(role='singleton'))
);
CREATE OR REPLACE FUNCTION finance_group_key(d jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT finance_document_hash(jsonb_build_object('singleton',d#>>'{singleton,portionId}','members',(SELECT jsonb_agg(x->>'portionId' ORDER BY x->>'portionId') FROM jsonb_array_elements(d->'members') x)))
$$;
CREATE OR REPLACE FUNCTION finance_group_ref(r jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT jsonb_typeof(r)='object' AND (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key)=ARRAY['documentId','observationId','portionId']
 AND finance_supply_id(r->'documentId') AND finance_supply_id(r->'observationId') AND finance_supply_id(r->'portionId')
$$;
CREATE OR REPLACE FUNCTION finance_group_input(p jsonb,p_save boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE d jsonb;r jsonb;keys text[]:=ARRAY['draft','caseId','expectedVersion','expectedRevisionId'];
BEGIN
 IF p_save THEN keys:=keys||ARRAY['expectedPreviewHash','requestId'];END IF;
 IF jsonb_typeof(p)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p) key) IS DISTINCT FROM (SELECT array_agg(k ORDER BY k) FROM unnest(keys) k)
 OR NOT vat_followup_money(p->'expectedVersion') OR (p->>'expectedVersion')::numeric>2147483646 THEN RETURN false;END IF;
 IF p->'expectedVersion'='0'::jsonb THEN IF p->'caseId'<>'null'::jsonb OR p->'expectedRevisionId'<>'null'::jsonb THEN RETURN false;END IF;
 ELSIF NOT finance_supply_id(p->'caseId') OR NOT finance_supply_id(p->'expectedRevisionId') THEN RETURN false;END IF;
 IF p_save AND (NOT finance_supply_id(p->'requestId') OR COALESCE(p->>'expectedPreviewHash','') !~ '^[a-f0-9]{64}$') THEN RETURN false;END IF;
 d:=p->'draft';IF jsonb_typeof(d)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(d) key) IS DISTINCT FROM ARRAY['coverageConfirmed','currencyEvidence','evidenceManifestId','members','reason','reviewRevisionId','singleton','subjectId']
 OR NOT finance_supply_id(d->'subjectId') OR NOT finance_supply_id(d->'reviewRevisionId') OR NOT finance_supply_id(d->'evidenceManifestId')
 OR d->'coverageConfirmed' IS DISTINCT FROM 'true'::jsonb OR length(btrim(d->>'reason')) NOT BETWEEN 1 AND 2000 OR d->>'reason' IS NULL OR NOT finance_group_ref(d->'singleton')
 OR jsonb_typeof(d->'members')<>'array' OR jsonb_array_length(d->'members') NOT BETWEEN 2 AND 20
 OR jsonb_typeof(d->'currencyEvidence')<>'array' OR jsonb_array_length(d->'currencyEvidence')<>jsonb_array_length(d->'members')+1 THEN RETURN false;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(d->'members') LOOP IF finance_group_ref(r) IS DISTINCT FROM true THEN RETURN false;END IF;END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(d->'currencyEvidence') LOOP
 IF jsonb_typeof(r)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY['currency','documentId','manifestRegionId']
 OR NOT finance_supply_id(r->'documentId') OR NOT finance_supply_id(r->'manifestRegionId') OR r->>'currency' IS DISTINCT FROM 'KRW' THEN RETURN false;END IF;END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
CREATE OR REPLACE FUNCTION finance_group_evidence_valid(p jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE a jsonb;r jsonb;box jsonb;pg jsonb; k text;ids text[]:='{}';
BEGIN
 IF jsonb_typeof(p)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p) key) IS DISTINCT FROM ARRAY['adapter','documentId','evidenceHash','regions','requestId','subjectId']
 OR NOT finance_supply_id(p->'subjectId') OR NOT finance_supply_id(p->'documentId') OR NOT finance_supply_id(p->'requestId') OR COALESCE(p->>'evidenceHash','') !~ '^[a-f0-9]{64}$' THEN RETURN false;END IF;
 a:=p->'adapter';IF jsonb_typeof(a)<>'object' OR a->>'verificationLevel' IS DISTINCT FROM 'human_review' OR a->>'documentHash' IS DISTINCT FROM p->>'evidenceHash'
 OR length(COALESCE(a->>'adapterVersion','')) NOT BETWEEN 1 AND 100 OR NOT vat_followup_money(a->'pageCount') OR (a->>'pageCount')::integer NOT BETWEEN 1 AND 20
 OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(a) key) IS DISTINCT FROM ARRAY['adapterVersion','documentHash','pageCount','pages','regions','schemaVersion','verificationLevel']
 OR a->>'schemaVersion' IS DISTINCT FROM 'supply-group-pdf-v1' OR jsonb_typeof(a->'pages')<>'array' OR jsonb_array_length(a->'pages') NOT BETWEEN 1 AND 20 OR jsonb_typeof(a->'regions')<>'array'
 OR jsonb_typeof(p->'regions')<>'array' OR jsonb_array_length(p->'regions') NOT BETWEEN 1 AND 64 OR jsonb_array_length(a->'regions')<>jsonb_array_length(p->'regions') THEN RETURN false;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p->'regions') LOOP
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY['pageNumber','rect','regionId','role','wholeRefs'] OR NOT finance_supply_id(r->'regionId') OR r->>'regionId'=ANY(ids) OR r->>'role' NOT IN('context','detail') OR NOT vat_followup_money(r->'pageNumber')
 OR (r->>'pageNumber')::integer NOT BETWEEN 1 AND (a->>'pageCount')::integer OR jsonb_typeof(r->'wholeRefs')<>'array' OR jsonb_array_length(r->'wholeRefs') NOT BETWEEN 1 AND 21 THEN RETURN false;END IF;
 ids:=ids||ARRAY[r->>'regionId'];box:=r->'rect';IF jsonb_typeof(box)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(box) key) IS DISTINCT FROM ARRAY['height','width','x','y'] THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['x','y','width','height']) LOOP IF jsonb_typeof(box->k)<>'number' OR (box->>k)::numeric<0 OR (box->>k)::numeric>1 THEN RETURN false;END IF;END LOOP;
 IF (box->>'width')::numeric<=0 OR (box->>'height')::numeric<=0 OR (box->>'x')::numeric+(box->>'width')::numeric>1 OR (box->>'y')::numeric+(box->>'height')::numeric>1 THEN RETURN false;END IF;
 FOR pg IN SELECT value FROM jsonb_array_elements(r->'wholeRefs') LOOP IF finance_group_ref(pg) IS DISTINCT FROM true THEN RETURN false;END IF;END LOOP;
 IF (SELECT count(*) FROM jsonb_array_elements(a->'regions') z WHERE z->>'regionId'=r->>'regionId')<>1 THEN RETURN false;END IF;
 SELECT z INTO pg FROM jsonb_array_elements(a->'regions') z WHERE z->>'regionId'=r->>'regionId';
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(pg) key) IS DISTINCT FROM ARRAY['contentHash','locator','previewHash','regionId','textHash','textStatus']
 OR pg->>'textStatus' NOT IN('text','no_text') OR COALESCE(pg->>'contentHash','') !~ '^[a-f0-9]{64}$' OR COALESCE(pg->>'previewHash','') !~ '^[a-f0-9]{64}$' OR COALESCE(pg->>'textHash','') !~ '^[a-f0-9]{64}$'
 OR pg->'locator' IS DISTINCT FROM jsonb_build_object('kind','pdf-region','coordinateSystem','rotated-top-left-normalized-v1','pageNumber',r->'pageNumber','x',box->'x','y',box->'y','width',box->'width','height',box->'height') THEN RETURN false;END IF;
 END LOOP;
 ids:='{}';FOR pg IN SELECT value FROM jsonb_array_elements(a->'pages') LOOP
 IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(pg) key) IS DISTINCT FROM ARRAY['height','imageHash','pageNumber','renderHeight','renderWidth','rotation','width']
 OR NOT vat_followup_money(pg->'pageNumber') OR (pg->>'pageNumber')::integer NOT BETWEEN 1 AND (a->>'pageCount')::integer OR pg->>'pageNumber'=ANY(ids)
 OR COALESCE(pg->>'imageHash','') !~ '^[a-f0-9]{64}$' OR pg->>'rotation' NOT IN('0','90','180','270')
 OR jsonb_typeof(pg->'width')<>'number' OR (pg->>'width')::numeric<=0 OR jsonb_typeof(pg->'height')<>'number' OR (pg->>'height')::numeric<=0
 OR NOT vat_followup_money(pg->'renderWidth') OR NOT vat_followup_money(pg->'renderHeight') OR (pg->>'renderWidth')::numeric<=0 OR (pg->>'renderHeight')::numeric<=0
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'regions') z WHERE z->'pageNumber'=pg->'pageNumber') THEN RETURN false;END IF;ids:=ids||ARRAY[pg->>'pageNumber'];END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'regions') z WHERE NOT(z->>'pageNumber'=ANY(ids))) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
CREATE OR REPLACE FUNCTION finance_group_fence_write() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(1296256326,1);
 UPDATE finance_group_fence SET version=version+1 WHERE fence_id=1;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group relation fence unavailable' USING ERRCODE='55000';END IF;
END $$;
CREATE OR REPLACE FUNCTION finance_group_candidate(p_input jsonb,p_ignore_case text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE d jsonb;one jsonb;side jsonb;ref jsonb;ev finance_group_evidence%ROWTYPE;last_row finance_group_revisions%ROWTYPE;root_row finance_group_cases%ROWTYPE;
 issues jsonb:='[]';members jsonb:='[]';sides jsonb:='[]';times jsonb:='[]';relations jsonb;basis jsonb;result jsonb;currency jsonb;region jsonb;sum_supply numeric:=0;sum_tax numeric:=0;sum_total numeric:=0;
 all_refs jsonb;other record;region2 jsonb;reference_doc jsonb;
BEGIN
 IF finance_group_input(p_input) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Invalid whole group input' USING ERRCODE='22023';END IF;
 d:=p_input->'draft';one:=finance_same_side(d,d->'singleton');issues:=issues||(one->'issues');times:=times||(one->'times');all_refs:=jsonb_build_array(d->'singleton')||(d->'members');
 FOR ref IN SELECT value FROM jsonb_array_elements(d->'members') LOOP
 side:=finance_same_side(d,ref);issues:=issues||(side->'issues');times:=times||(side->'times');members:=members||jsonb_build_array(side->'summary');sides:=sides||jsonb_build_array(side);
 IF side->'summary' IS NULL OR side->'summary'='null'::jsonb OR side#>>'{summary,direction}' IS DISTINCT FROM one#>>'{summary,direction}' OR side->>'counterparty' IS DISTINCT FROM one->>'counterparty' THEN issues:=issues||finance_document_issue('group_counterparty_mismatch','기준과 구성원의 회사·방향·거래처를 확인하세요.');END IF;
 IF COALESCE((side#>>'{summary,supply}')::numeric,0)<0 OR COALESCE((side#>>'{summary,tax}')::numeric,0)<0 OR COALESCE((side#>>'{summary,total}')::numeric,0)<=0 THEN issues:=issues||finance_document_issue('group_amount_unsupported','양수 전체 문서만 지원합니다. 취소액을 상계하지 않습니다.');END IF;
 sum_supply:=sum_supply+COALESCE((side#>>'{summary,supply}')::numeric,0);sum_tax:=sum_tax+COALESCE((side#>>'{summary,tax}')::numeric,0);sum_total:=sum_total+COALESCE((side#>>'{summary,total}')::numeric,0);
 END LOOP;
 IF sum_supply IS DISTINCT FROM (one#>>'{summary,supply}')::numeric OR sum_tax IS DISTINCT FROM (one#>>'{summary,tax}')::numeric OR sum_total IS DISTINCT FROM (one#>>'{summary,total}')::numeric
 OR sum_total<>sum_supply+sum_tax OR sum_total<=0 OR sum_total>9007199254740991 THEN issues:=issues||finance_document_issue('group_amount_mismatch','기준 전체와 구성원 전체의 공급가액·세액·합계를 각각 맞추세요.');END IF;
 SELECT * INTO ev FROM finance_group_evidence WHERE manifest_id=d->>'evidenceManifestId';
 IF NOT FOUND OR ev.subject_id IS DISTINCT FROM d->>'subjectId' THEN issues:=issues||finance_document_issue('group_evidence_unavailable','같은 회사의 보관 원문 위치 근거를 선택하세요.');
 ELSE
 PERFORM finance_group_assert_request(ev.request_id);reference_doc:=finance_same_document(ev.document_id,ev.subject_id,ev.document_hash);
 IF reference_doc IS NULL THEN issues:=issues||finance_document_issue('group_evidence_unavailable','보관 원문 근거를 확인할 수 없습니다.');END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(all_refs) LOOP
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ev.payload_json->'regions') z CROSS JOIN LATERAL jsonb_array_elements(z->'wholeRefs') w WHERE w=ref AND (ref=d->'singleton' OR z->>'role'='detail'))
 THEN issues:=issues||finance_document_issue('group_coverage_missing','기준 문서의 원문 위치와 각 구성원의 세부 원문 위치가 필요합니다.');END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(d->'currencyEvidence') c WHERE c->>'documentId'=ref->>'documentId')<>1 THEN issues:=issues||finance_document_issue('group_currency_unavailable','각 문서의 통화 원문 근거를 지정하세요.');
 ELSE
 SELECT c INTO currency FROM jsonb_array_elements(d->'currencyEvidence') c WHERE c->>'documentId'=ref->>'documentId';
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ev.payload_json->'regions') z CROSS JOIN LATERAL jsonb_array_elements(z->'wholeRefs') w WHERE z->>'regionId'=currency->>'manifestRegionId' AND w=ref)
 THEN issues:=issues||finance_document_issue('group_currency_unavailable','통화 표시가 있는 실제 원문 영역과 문서를 결속하세요.');END IF;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(ev.payload_json->'regions') z CROSS JOIN LATERAL jsonb_array_elements(z->'wholeRefs') w WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(all_refs) a WHERE a=w)) THEN issues:=issues||finance_document_issue('group_coverage_extra','다른 문서가 섞인 원문 대응 범위를 다시 선택하세요.');END IF;
 FOR region IN SELECT value FROM jsonb_array_elements(ev.payload_json->'regions') WHERE value->>'role'='detail' LOOP
 IF (SELECT count(DISTINCT w->>'portionId') FROM jsonb_array_elements(region->'wholeRefs') w WHERE w->>'portionId'<>d#>>'{singleton,portionId}')>1 THEN issues:=issues||finance_document_issue('group_detail_overlap','같은 세부 원문 영역을 여러 구성원에 중복 배정할 수 없습니다.');END IF;
 FOR region2 IN SELECT value FROM jsonb_array_elements(ev.payload_json->'regions') WHERE value->>'role'='detail' AND value->>'regionId'>region->>'regionId' LOOP
 IF region->'pageNumber'=region2->'pageNumber' AND (region#>>'{rect,x}')::numeric<(region2#>>'{rect,x}')::numeric+(region2#>>'{rect,width}')::numeric AND (region2#>>'{rect,x}')::numeric<(region#>>'{rect,x}')::numeric+(region#>>'{rect,width}')::numeric
 AND (region#>>'{rect,y}')::numeric<(region2#>>'{rect,y}')::numeric+(region2#>>'{rect,height}')::numeric AND (region2#>>'{rect,y}')::numeric<(region#>>'{rect,y}')::numeric+(region#>>'{rect,height}')::numeric
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(region->'wholeRefs') a CROSS JOIN jsonb_array_elements(region2->'wholeRefs') b WHERE a->>'portionId'<>d#>>'{singleton,portionId}' AND b->>'portionId'<>d#>>'{singleton,portionId}' AND a->>'portionId'<>b->>'portionId')
 THEN issues:=issues||finance_document_issue('group_detail_overlap','서로 다른 구성원의 세부 원문 영역이 겹칩니다. 공통 제목은 context로 구분하세요.');END IF;
 END LOOP;END LOOP;
 END IF;
 IF p_ignore_case IS NULL THEN
 IF p_input->>'caseId' IS NOT NULL THEN
 SELECT * INTO root_row FROM finance_group_cases WHERE case_id=p_input->>'caseId';SELECT * INTO last_row FROM finance_group_revisions WHERE case_id=p_input->>'caseId' ORDER BY version DESC LIMIT 1;
 IF root_row.subject_id IS DISTINCT FROM d->>'subjectId' OR root_row.group_key IS DISTINCT FROM finance_group_key(d) OR last_row.version IS DISTINCT FROM (p_input->>'expectedVersion')::integer OR last_row.revision_id IS DISTINCT FROM p_input->>'expectedRevisionId' THEN issues:=issues||finance_document_issue('group_revision_stale','같은 문서 집합의 최신판을 다시 선택하세요.');END IF;
 ELSIF EXISTS(SELECT 1 FROM finance_group_cases WHERE subject_id=d->>'subjectId' AND group_key=finance_group_key(d)) THEN issues:=issues||finance_document_issue('group_case_exists','이미 등록된 정확 집합의 최신판을 선택하세요.');END IF;END IF;
 relations:=finance_group_relations(d,true);issues:=issues||(relations->'issues');
 FOR other IN SELECT v.* FROM finance_group_revisions v JOIN finance_group_cases c USING(case_id) WHERE c.subject_id=d->>'subjectId' AND v.state='verified_group' AND c.case_id IS DISTINCT FROM COALESCE(p_input->>'caseId',p_ignore_case)
 AND NOT EXISTS(SELECT 1 FROM finance_group_revisions n WHERE n.case_id=v.case_id AND n.version>v.version) LOOP
 IF finance_group_component(d->>'subjectId',d#>>'{singleton,portionId}') && finance_group_component(d->>'subjectId',other.input_json#>>'{draft,singleton,portionId}')
 AND (SELECT jsonb_agg(to_jsonb(finance_group_component(d->>'subjectId',x->>'portionId')) ORDER BY finance_group_component(d->>'subjectId',x->>'portionId')) FROM jsonb_array_elements(d->'members') x)
 IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(finance_group_component(d->>'subjectId',x->>'portionId')) ORDER BY finance_group_component(d->>'subjectId',x->>'portionId')) FROM jsonb_array_elements(other.input_json#>'{draft,members}') x)
 THEN issues:=issues||finance_document_issue('group_overlap_unresolved','같은 기준 문서의 다른 전체 분해는 추가 대응 근거가 필요합니다.');END IF;
 END LOOP;
 basis:=jsonb_build_object('version','de1b-group-basis-v1','singleton',one,'members',sides,'evidence',jsonb_build_object('manifestId',ev.manifest_id,'manifestHash',ev.manifest_hash,'verificationLevel','human_review'),'relations',relations);
 result:=jsonb_build_object('schemaVersion','de1b-group-preview-v1','draft',d,'canVerify',jsonb_array_length(issues)=0,'issues',issues,'singleton',one->'summary','members',members,'timeDiagnostics',times,'financialUseSupported',false);
 RETURN result||jsonb_build_object('previewHash',finance_document_hash(jsonb_build_object('input',p_input,'result',result,'basis',basis)),'_basis',basis);
END $$;
CREATE OR REPLACE FUNCTION finance_group_preview(p_input jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT finance_group_candidate(p_input)-'_basis' $$;
CREATE OR REPLACE FUNCTION finance_group_lock() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM finance_group_fence_write();PERFORM finance_same_lock();
 LOCK TABLE finance_same_cases,finance_same_revisions,finance_same_requests,finance_group_cases,finance_group_revisions,finance_group_members,finance_group_evidence,finance_group_requests IN SHARE MODE;
END $$;
CREATE OR REPLACE FUNCTION finance_group_component(p_subject text,p_portion text) RETURNS text[] LANGUAGE sql STABLE AS $$
 WITH RECURSIVE edges AS (
 SELECT v.input_json#>>'{draft,left,portionId}' a,v.input_json#>>'{draft,right,portionId}' b FROM finance_same_revisions v JOIN finance_same_cases c USING(case_id)
 WHERE c.subject_id=p_subject AND v.state='verified_same' AND NOT EXISTS(SELECT 1 FROM finance_same_revisions n WHERE n.case_id=v.case_id AND n.version>v.version)),
 walk(p) AS (SELECT p_portion UNION SELECT CASE WHEN e.a=w.p THEN e.b ELSE e.a END FROM walk w JOIN edges e ON e.a=w.p OR e.b=w.p)
 SELECT array_agg(p ORDER BY p) FROM walk
$$;
CREATE OR REPLACE FUNCTION finance_group_relations(d jsonb,p_current boolean DEFAULT true) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE components jsonb:='[]';component text[];all_portions text[]:='{}';anchor text[];anchor_docs text[];member_docs text[];all_docs text[];previous text[]:='{}';
 refs jsonb:='[]';graph jsonb:='[]';links jsonb:='[]';issues jsonb:='[]';x jsonb;f jsonb;g jsonb;e record;target jsonb;member_index integer:=0;conflict boolean;
BEGIN
 anchor:=finance_group_component(d->>'subjectId',d#>>'{singleton,portionId}');
 FOR x IN SELECT value FROM jsonb_array_elements(jsonb_build_array(d->'singleton')||(d->'members')) LOOP
 component:=finance_group_component(d->>'subjectId',x->>'portionId');
 IF component && previous THEN issues:=issues||finance_document_issue('group_identity_overlap','구성원이 같은 whole 또는 같은 1:1 대표를 중복 참조합니다.');END IF;
 previous:=previous||component;all_portions:=all_portions||component;components:=components||jsonb_build_array(jsonb_build_object('ref',x,'portions',to_jsonb(component),'role',CASE WHEN member_index=0 THEN 'singleton' ELSE 'member' END));member_index:=member_index+1;
 END LOOP;
 SELECT array_agg(DISTINCT document_id ORDER BY document_id) INTO anchor_docs FROM finance_document_portions WHERE portion_id=ANY(anchor);
 SELECT array_agg(DISTINCT document_id ORDER BY document_id) INTO member_docs FROM finance_document_portions WHERE portion_id=ANY(all_portions) AND NOT(portion_id=ANY(anchor));
 all_docs:=COALESCE(anchor_docs,'{}')||COALESCE(member_docs,'{}');
 FOR e IN SELECT v.* FROM finance_same_revisions v JOIN finance_same_cases c USING(case_id) WHERE c.subject_id=d->>'subjectId' AND v.state='verified_same'
 AND NOT EXISTS(SELECT 1 FROM finance_same_revisions n WHERE n.case_id=v.case_id AND n.version>v.version)
 AND (v.input_json#>>'{draft,left,portionId}'=ANY(all_portions) OR v.input_json#>>'{draft,right,portionId}'=ANY(all_portions)) ORDER BY v.revision_id LOOP
 IF p_current THEN f:=finance_same_side(e.input_json->'draft',e.input_json#>'{draft,left}');g:=finance_same_side(e.input_json->'draft',e.input_json#>'{draft,right}');
 IF f->'issues'<>'[]'::jsonb OR g->'issues'<>'[]'::jsonb OR f IS DISTINCT FROM e.basis_json->'left' OR g IS DISTINCT FROM e.basis_json->'right' THEN issues:=issues||finance_document_issue('group_same_stale','대표 정규화에 사용한 1:1 관계를 다시 대조하세요.');END IF;END IF;
 graph:=graph||jsonb_build_array(jsonb_build_object('revisionId',e.revision_id,'proofHash',e.proof_hash));
 END LOOP;
 FOR e IN SELECT * FROM transaction_links WHERE relation='distinct' AND state='active' ORDER BY link_id LOOP
 conflict:=(EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(anchor_docs) AND s.source_kind=e.left_kind AND s.source_id=e.left_id)
 AND EXISTS(SELECT 1 FROM finance_document_sources s JOIN finance_document_registry r USING(document_id) WHERE s.document_id=ANY(member_docs) AND (s.source_kind=e.right_kind AND s.source_id=e.right_id OR e.canonical_invoice_key='invoice:'||(r.descriptor_json->>1))))
 OR (EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(member_docs) AND s.source_kind=e.left_kind AND s.source_id=e.left_id)
 AND EXISTS(SELECT 1 FROM finance_document_sources s JOIN finance_document_registry r USING(document_id) WHERE s.document_id=ANY(anchor_docs) AND (s.source_kind=e.right_kind AND s.source_id=e.right_id OR e.canonical_invoice_key='invoice:'||(r.descriptor_json->>1))));
 IF conflict THEN links:=links||jsonb_build_array(jsonb_build_object('linkId',e.link_id,'snapshotHash',finance_document_hash(to_jsonb(e))));issues:=issues||finance_document_issue('group_distinct_conflict','기준 문서와 구성원 사이의 별개 공급 선언을 해소하세요.');END IF;
 END LOOP;
 FOR e IN SELECT p.*,v.state,v.payload_hash,v.payload_json,v.review_id,c.consumption_id FROM vat_followup_review_pairs p JOIN vat_followup_review_revisions v USING(revision_id) JOIN vat_followup_review_roots root USING(review_id)
 LEFT JOIN vat_followup_review_consumptions c ON c.revision_id=p.revision_id AND c.pair_line_no=p.line_no
 WHERE root.subject_id=d->>'subjectId' AND (c.consumption_id IS NOT NULL OR v.state='verified' AND NOT EXISTS(SELECT 1 FROM vat_followup_review_revisions n WHERE n.review_id=v.review_id AND n.version>v.version))
 AND (EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(all_docs) AND s.source_kind='card' AND s.source_id=p.card_source_id)
 OR EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(all_docs) AND s.source_kind='hometax' AND s.source_id=p.invoice_source_id)) ORDER BY p.revision_id,p.line_no LOOP
 IF e.state<>'verified' OR e.payload_hash IS DISTINCT FROM vat_followup_hash(e.payload_json) OR e.payload_json#>ARRAY['pairs',e.line_no::text] IS DISTINCT FROM e.pair_json THEN RAISE EXCEPTION 'Group C pair archive mismatch' USING ERRCODE='55000';END IF;
 IF p_current AND e.pair_json->'databaseProof' IS DISTINCT FROM vat_followup_database_proof(e.card_source_id,e.invoice_source_id,e.legacy_return_id,e.past_basis_snapshot_id,e.past_fact_revision_id) THEN issues:=issues||finance_document_issue('group_c_source_stale','관련 C 정확 쌍의 원천 근거를 다시 대조하세요.');END IF;
 target:=CASE WHEN e.consumption_id IS NOT NULL AND p_current THEN finance_same_c_target(e.consumption_id,d->>'subjectId') ELSE NULL END;
 refs:=refs||jsonb_build_array(jsonb_build_object('revisionId',e.revision_id,'pairLineNo',e.line_no,'pairHash',finance_document_hash(e.pair_json),'consumptionId',e.consumption_id,'targetProof',target,'claimedTax',e.pair_json#>'{past,claim,claimedTax}','claimedSupply',NULL));
 conflict:=(EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(anchor_docs) AND s.source_kind='card' AND s.source_id=e.card_source_id) AND EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(member_docs) AND s.source_kind='hometax' AND s.source_id=e.invoice_source_id))
 OR(EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(member_docs) AND s.source_kind='card' AND s.source_id=e.card_source_id) AND EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(anchor_docs) AND s.source_kind='hometax' AND s.source_id=e.invoice_source_id));
 IF conflict THEN issues:=issues||finance_document_issue('group_c_distinct_conflict','기준과 구성원 사이의 정확 C 별개 공급 선언과 충돌합니다.');END IF;
 END LOOP;
 RETURN jsonb_build_object('issues',issues,'components',components,'sameReferences',graph,'distinctLinks',links,'cReferences',refs);
END $$;
CREATE OR REPLACE FUNCTION finance_group_assert_request(p_request text) RETURNS void LANGUAGE plpgsql STABLE AS $$
DECLARE q finance_group_requests%ROWTYPE;v finance_group_revisions%ROWTYPE;c finance_group_cases%ROWTYPE;e finance_group_evidence%ROWTYPE;prior finance_group_revisions%ROWTYPE;
 expected jsonb;actual jsonb;fresh jsonb;input jsonb;member jsonb;idx integer:=0;
BEGIN
 SELECT * INTO STRICT q FROM finance_group_requests WHERE request_id=p_request;
 IF q.payload_hash IS DISTINCT FROM finance_document_hash(q.payload_json) OR NOT finance_supply_id(to_jsonb(q.actor_user_id)) OR NOT finance_supply_id(to_jsonb(q.request_id)) OR q.payload_json->>'requestId' IS DISTINCT FROM q.request_id THEN RAISE EXCEPTION 'Group request integrity mismatch' USING ERRCODE='23514';END IF;
 IF q.action='evidence' THEN
 SELECT * INTO STRICT e FROM finance_group_evidence WHERE request_id=q.request_id;
 IF e.payload_json IS DISTINCT FROM q.payload_json OR e.manifest_hash IS DISTINCT FROM finance_document_hash(e.payload_json) OR e.actor_user_id IS DISTINCT FROM q.actor_user_id
 OR e.subject_id IS DISTINCT FROM e.payload_json->>'subjectId' OR e.document_id IS DISTINCT FROM e.payload_json->>'documentId' OR e.document_hash IS DISTINCT FROM e.payload_json->>'evidenceHash'
 OR e.verification_level<>'human_review' OR finance_group_evidence_valid(e.payload_json) IS DISTINCT FROM true OR finance_same_document(e.document_id,e.subject_id,e.document_hash) IS NULL THEN RAISE EXCEPTION 'Group evidence archive mismatch' USING ERRCODE='23514';END IF;
 expected:=jsonb_build_object('manifestId',e.manifest_id,'manifestHash',e.manifest_hash,'verificationLevel','human_review','replayed',false);
 ELSE
 SELECT * INTO STRICT v FROM finance_group_revisions WHERE request_id=q.request_id;SELECT * INTO STRICT c FROM finance_group_cases WHERE case_id=v.case_id;
 IF v.actor_user_id IS DISTINCT FROM q.actor_user_id OR v.proof_hash IS DISTINCT FROM finance_document_hash(jsonb_build_object('input',v.input_json,'preview',v.preview_json,'basis',v.basis_json))
 OR c.subject_id IS DISTINCT FROM v.input_json#>>'{draft,subjectId}' OR c.group_key IS DISTINCT FROM finance_group_key(v.input_json->'draft') OR finance_group_input(v.input_json) IS DISTINCT FROM true
 OR v.preview_json->'financialUseSupported' IS DISTINCT FROM 'false'::jsonb OR v.preview_json->'canVerify' IS DISTINCT FROM 'true'::jsonb OR v.preview_json->'issues' IS DISTINCT FROM '[]'::jsonb
 THEN RAISE EXCEPTION 'Group archive integrity mismatch' USING ERRCODE='23514';END IF;
 SELECT * INTO prior FROM finance_group_revisions WHERE case_id=v.case_id AND version=v.version-1;
 IF (v.version=1 AND (c.created_request_id IS DISTINCT FROM v.request_id OR c.actor_user_id IS DISTINCT FROM v.actor_user_id OR v.previous_revision_id IS NOT NULL))
 OR (v.version>1 AND (prior.revision_id IS NULL OR prior.revision_id IS DISTINCT FROM v.previous_revision_id)) THEN RAISE EXCEPTION 'Group archive chain mismatch' USING ERRCODE='23514';END IF;
 IF q.action='verify' THEN
 IF v.state<>'verified_group' OR finance_group_input(q.payload_json,true) IS DISTINCT FROM true OR q.payload_json-ARRAY['expectedPreviewHash','requestId'] IS DISTINCT FROM v.input_json
 OR q.payload_json->>'expectedPreviewHash' IS DISTINCT FROM v.preview_json->>'previewHash'
 OR (v.input_json->>'expectedVersion')::integer<>v.version-1 OR v.input_json->>'expectedRevisionId' IS DISTINCT FROM prior.revision_id
 OR v.input_json->>'caseId' IS DISTINCT FROM (CASE WHEN v.version=1 THEN NULL ELSE v.case_id END) THEN RAISE EXCEPTION 'Group verified request mismatch' USING ERRCODE='23514';END IF;
 IF v.apply_xid=pg_current_xact_id_if_assigned() THEN
 fresh:=finance_group_candidate(v.input_json,v.case_id);IF fresh->>'canVerify' IS DISTINCT FROM 'true' OR fresh-'_basis' IS DISTINCT FROM v.preview_json OR fresh->'_basis' IS DISTINCT FROM v.basis_json THEN RAISE EXCEPTION 'Group current proof changed before commit' USING ERRCODE='23514';END IF;END IF;
 ELSE
 IF v.state<>'withdrawn' OR prior.state<>'verified_group' OR v.input_json IS DISTINCT FROM prior.input_json OR v.preview_json IS DISTINCT FROM prior.preview_json OR v.basis_json IS DISTINCT FROM prior.basis_json
 OR q.payload_json->>'caseId' IS DISTINCT FROM v.case_id OR q.payload_json->>'subjectId' IS DISTINCT FROM c.subject_id OR q.payload_json->>'expectedRevisionId' IS DISTINCT FROM prior.revision_id
 OR (q.payload_json->>'expectedVersion')::integer<>prior.version OR q.payload_json->>'reason' IS DISTINCT FROM v.withdrawal_reason THEN RAISE EXCEPTION 'Group withdrawal request mismatch' USING ERRCODE='23514';END IF;END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('memberNo',member_no,'role',role,'documentId',document_id,'portionId',portion_id,'observationId',observation_id,'summary',summary_json) ORDER BY member_no),'[]') INTO actual FROM finance_group_members WHERE revision_id=v.revision_id;
 expected:='[]';FOR member IN SELECT value FROM jsonb_array_elements(jsonb_build_array(v.preview_json->'singleton')||(v.preview_json->'members')) LOOP
 IF NOT EXISTS(SELECT 1 FROM finance_document_portions p JOIN finance_document_observations o USING(document_id) WHERE p.portion_id=member->>'portionId' AND p.locator='whole' AND o.observation_id=member->>'observationId' AND o.subject_id=c.subject_id)
 THEN RAISE EXCEPTION 'Group archived whole reference missing' USING ERRCODE='23514';END IF;
 expected:=expected||jsonb_build_array(jsonb_build_object('memberNo',idx,'role',CASE WHEN idx=0 THEN 'singleton' ELSE 'member' END,'documentId',member->>'documentId','portionId',member->>'portionId','observationId',member->>'observationId','summary',member));idx:=idx+1;
 END LOOP;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Group exact member set mismatch' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT e FROM finance_group_evidence WHERE manifest_id=v.input_json#>>'{draft,evidenceManifestId}';PERFORM finance_group_assert_request(e.request_id);
 IF v.basis_json#>>'{evidence,manifestHash}' IS DISTINCT FROM e.manifest_hash OR e.subject_id<>c.subject_id THEN RAISE EXCEPTION 'Group evidence reference mismatch' USING ERRCODE='23514';END IF;
 expected:=jsonb_build_object('caseId',v.case_id,'revisionId',v.revision_id,'version',v.version,'state',v.state,'replayed',false,'financialUseSupported',false);
 END IF;
 IF q.result_json IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Group result mismatch' USING ERRCODE='23514';END IF;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'Group complete request missing' USING ERRCODE='23514';END $$;
CREATE OR REPLACE FUNCTION finance_group_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Group review history is immutable' USING ERRCODE='23514';END $$;
CREATE OR REPLACE FUNCTION finance_group_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE prior finance_group_revisions%ROWTYPE;c finance_group_cases%ROWTYPE;fresh jsonb;
BEGIN
 PERFORM finance_group_lock();PERFORM finance_assert_group_definitions(current_schema());
 IF TG_TABLE_NAME='finance_group_evidence' THEN
 IF finance_group_evidence_valid(NEW.payload_json) IS DISTINCT FROM true OR finance_same_document(NEW.document_id,NEW.subject_id,NEW.document_hash) IS NULL THEN RAISE EXCEPTION 'Invalid group evidence binding' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME='finance_group_revisions' THEN
 SELECT * INTO STRICT c FROM finance_group_cases WHERE case_id=NEW.case_id;SELECT * INTO prior FROM finance_group_revisions WHERE case_id=NEW.case_id ORDER BY version DESC LIMIT 1;
 IF NEW.version<>COALESCE(prior.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM prior.revision_id OR NEW.apply_xid<>pg_current_xact_id() OR NOT finance_group_input(NEW.input_json)
 OR c.subject_id IS DISTINCT FROM NEW.input_json#>>'{draft,subjectId}' OR c.group_key IS DISTINCT FROM finance_group_key(NEW.input_json->'draft') THEN RAISE EXCEPTION 'Group revision chain conflict' USING ERRCODE='23514';END IF;
 IF NEW.state='verified_group' THEN
 IF (NEW.input_json->>'expectedVersion')::integer<>COALESCE(prior.version,0) OR NEW.input_json->>'expectedRevisionId' IS DISTINCT FROM prior.revision_id THEN RAISE EXCEPTION 'Group expected revision conflict' USING ERRCODE='23514';END IF;
 fresh:=finance_group_candidate(NEW.input_json,NEW.case_id);IF fresh->>'canVerify' IS DISTINCT FROM 'true' OR fresh-'_basis' IS DISTINCT FROM NEW.preview_json OR fresh->'_basis' IS DISTINCT FROM NEW.basis_json THEN RAISE EXCEPTION 'Group current preview mismatch' USING ERRCODE='23514';END IF;
 ELSIF prior.state IS DISTINCT FROM 'verified_group' OR NEW.input_json IS DISTINCT FROM prior.input_json OR NEW.preview_json IS DISTINCT FROM prior.preview_json OR NEW.basis_json IS DISTINCT FROM prior.basis_json THEN RAISE EXCEPTION 'Group withdrawal copy mismatch' USING ERRCODE='23514';END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION finance_group_agreement() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE request text;v finance_group_revisions%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='finance_group_cases' THEN
 SELECT * INTO STRICT v FROM finance_group_revisions WHERE case_id=NEW.case_id AND version=1;
 IF v.request_id IS DISTINCT FROM NEW.created_request_id OR v.actor_user_id IS DISTINCT FROM NEW.actor_user_id OR v.input_json#>>'{draft,subjectId}' IS DISTINCT FROM NEW.subject_id OR finance_group_key(v.input_json->'draft') IS DISTINCT FROM NEW.group_key THEN RAISE EXCEPTION 'Group new root agreement mismatch' USING ERRCODE='23514';END IF;request:=NEW.created_request_id;
 ELSIF TG_TABLE_NAME='finance_group_members' THEN SELECT request_id INTO STRICT request FROM finance_group_revisions WHERE revision_id=NEW.revision_id;
 ELSE request:=NEW.request_id;END IF;
 PERFORM finance_group_assert_request(request);RETURN NULL;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'Group orphan record' USING ERRCODE='23514';END $$;
CREATE OR REPLACE FUNCTION finance_group_external_before() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN PERFORM finance_group_fence_write();PERFORM finance_assert_group_definitions(current_schema());RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION finance_group_external_complete() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v record;r jsonb;
BEGIN
 FOR v IN SELECT z.* FROM finance_group_revisions z WHERE z.state='verified_group' AND NOT EXISTS(SELECT 1 FROM finance_group_revisions n WHERE n.case_id=z.case_id AND n.version>z.version) LOOP
 r:=finance_group_relations(v.input_json->'draft',false);
 IF r->'issues'<>'[]'::jsonb THEN RAISE EXCEPTION 'New relation conflicts with a verified whole group' USING ERRCODE='23514',CONSTRAINT='finance_group_relation';END IF;
 END LOOP;RETURN NULL;
END $$;
DO $$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['finance_group_cases','finance_group_revisions','finance_group_members','finance_group_evidence','finance_group_requests'] LOOP
 EXECUTE format('DROP TRIGGER IF EXISTS finance_group_insert ON %I',t);EXECUTE format('CREATE TRIGGER finance_group_insert BEFORE INSERT ON %I FOR EACH ROW EXECUTE FUNCTION finance_group_insert()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_group_agreement ON %I',t);EXECUTE format('CREATE CONSTRAINT TRIGGER finance_group_agreement AFTER INSERT ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_group_agreement()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_group_immutable ON %I',t);EXECUTE format('CREATE TRIGGER finance_group_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION finance_group_immutable()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_group_no_truncate ON %I',t);EXECUTE format('CREATE TRIGGER finance_group_no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION finance_group_immutable()',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['vat_followup_review_revisions','vat_followup_review_pairs','vat_followup_review_consumptions','transaction_links','finance_same_revisions'] LOOP
 EXECUTE format('DROP TRIGGER IF EXISTS finance_group_external_before ON %I',t);EXECUTE format('CREATE TRIGGER finance_group_external_before BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION finance_group_external_before()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_group_external_complete ON %I',t);EXECUTE format('CREATE CONSTRAINT TRIGGER finance_group_external_complete AFTER INSERT OR UPDATE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_group_external_complete()',t);
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION finance_group_evidence_replay(p_client jsonb,p_actor text) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE q finance_group_requests%ROWTYPE;
BEGIN
 SELECT * INTO q FROM finance_group_requests WHERE request_id=p_client->>'requestId';IF NOT FOUND THEN RETURN NULL;END IF;
 IF q.action<>'evidence' OR q.actor_user_id IS DISTINCT FROM p_actor OR q.payload_json-'adapter' IS DISTINCT FROM p_client THEN RAISE EXCEPTION 'Group evidence request conflict' USING ERRCODE='23514';END IF;
 PERFORM finance_group_assert_request(q.request_id);RETURN q.result_json||jsonb_build_object('replayed',true);
END $$;
CREATE OR REPLACE FUNCTION finance_group_evidence_write(p_payload jsonb,p_actor text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE result jsonb;id text:='gme_'||md5(random()::text||clock_timestamp()::text);h text;
BEGIN
 PERFORM finance_group_lock();PERFORM finance_assert_group_definitions(current_schema());result:=finance_group_evidence_replay(p_payload-'adapter',p_actor);IF result IS NOT NULL THEN RETURN result;END IF;
 IF finance_group_evidence_valid(p_payload) IS DISTINCT FROM true OR NOT finance_supply_id(to_jsonb(p_actor)) THEN RAISE EXCEPTION 'Invalid group evidence input' USING ERRCODE='22023';END IF;
 IF finance_same_document(p_payload->>'documentId',p_payload->>'subjectId',p_payload->>'evidenceHash') IS NULL THEN RAISE EXCEPTION 'Group document unavailable' USING ERRCODE='23514';END IF;
 h:=finance_document_hash(p_payload);result:=jsonb_build_object('manifestId',id,'manifestHash',h,'verificationLevel','human_review','replayed',false);
 INSERT INTO finance_group_evidence(manifest_id,subject_id,document_id,document_hash,payload_json,manifest_hash,verification_level,actor_user_id,request_id) VALUES(id,p_payload->>'subjectId',p_payload->>'documentId',p_payload->>'evidenceHash',p_payload,h,'human_review',p_actor,p_payload->>'requestId');
 INSERT INTO finance_group_requests VALUES(p_payload->>'requestId','evidence',p_actor,p_payload,h,result,now());RETURN result;
END $$;
CREATE OR REPLACE FUNCTION finance_group_write(p_action text,p_input jsonb,p_request text,p_actor text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE q finance_group_requests%ROWTYPE;prior finance_group_revisions%ROWTYPE;c finance_group_cases%ROWTYPE;input jsonb;fresh jsonb;result jsonb;id text;revision text:='gvr_'||md5(random()::text||clock_timestamp()::text);version integer;member jsonb;idx integer:=0;state text;reason text;
BEGIN
 PERFORM finance_group_lock();PERFORM finance_assert_group_definitions(current_schema());
 IF p_input->>'requestId' IS DISTINCT FROM p_request OR NOT finance_supply_id(to_jsonb(p_actor)) OR NOT finance_supply_id(to_jsonb(p_request)) OR p_action NOT IN('verify','withdraw') THEN RAISE EXCEPTION 'Invalid group action' USING ERRCODE='22023';END IF;
 SELECT * INTO q FROM finance_group_requests WHERE request_id=p_request;
 IF FOUND THEN IF q.actor_user_id IS DISTINCT FROM p_actor OR q.action IS DISTINCT FROM p_action OR q.payload_json IS DISTINCT FROM p_input THEN RAISE EXCEPTION 'Group request conflict' USING ERRCODE='23514';END IF;PERFORM finance_group_assert_request(p_request);RETURN q.result_json||jsonb_build_object('replayed',true);END IF;
 IF p_action='verify' THEN
 IF finance_group_input(p_input,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Invalid group input' USING ERRCODE='22023';END IF;
 input:=p_input-ARRAY['expectedPreviewHash','requestId'];fresh:=finance_group_candidate(input);
 IF fresh->>'canVerify' IS DISTINCT FROM 'true' OR fresh->>'previewHash' IS DISTINCT FROM p_input->>'expectedPreviewHash' THEN RAISE EXCEPTION 'Group preview changed' USING ERRCODE='23514';END IF;
 id:=COALESCE(p_input->>'caseId','gcase_'||md5(random()::text||clock_timestamp()::text));SELECT * INTO prior FROM finance_group_revisions WHERE case_id=id ORDER BY version DESC LIMIT 1;version:=COALESCE(prior.version,0)+1;state:='verified_group';
 IF prior.revision_id IS NULL THEN INSERT INTO finance_group_cases VALUES(id,input#>>'{draft,subjectId}',finance_group_key(input->'draft'),p_request,p_actor,now());END IF;
 ELSE
 IF jsonb_typeof(p_input)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_input) key) IS DISTINCT FROM ARRAY['caseId','expectedRevisionId','expectedVersion','reason','requestId','subjectId'] OR NOT finance_supply_id(p_input->'caseId') OR NOT finance_supply_id(p_input->'subjectId') OR NOT vat_followup_money(p_input->'expectedVersion') OR length(btrim(p_input->>'reason')) NOT BETWEEN 1 AND 2000 OR p_input->>'reason' IS NULL THEN RAISE EXCEPTION 'Invalid group withdrawal' USING ERRCODE='22023';END IF;
 id:=p_input->>'caseId';SELECT * INTO c FROM finance_group_cases WHERE case_id=id;SELECT * INTO prior FROM finance_group_revisions WHERE case_id=id ORDER BY version DESC LIMIT 1;
 IF c.subject_id IS DISTINCT FROM p_input->>'subjectId' OR prior.state IS DISTINCT FROM 'verified_group' OR prior.version IS DISTINCT FROM (p_input->>'expectedVersion')::integer OR prior.revision_id IS DISTINCT FROM p_input->>'expectedRevisionId' THEN RAISE EXCEPTION 'Group withdrawal revision conflict' USING ERRCODE='23514';END IF;
 PERFORM finance_group_assert_request(prior.request_id);input:=prior.input_json;fresh:=prior.preview_json||jsonb_build_object('_basis',prior.basis_json);version:=prior.version+1;state:='withdrawn';reason:=p_input->>'reason';
 END IF;
 INSERT INTO finance_group_revisions(revision_id,case_id,version,previous_revision_id,schema_version,state,input_json,preview_json,basis_json,proof_hash,withdrawal_reason,request_id,actor_user_id)
 VALUES(revision,id,version,prior.revision_id,'de1b-group-revision-v1',state,input,fresh-'_basis',fresh->'_basis',finance_document_hash(jsonb_build_object('input',input,'preview',fresh-'_basis','basis',fresh->'_basis')),reason,p_request,p_actor);
 FOR member IN SELECT value FROM jsonb_array_elements(jsonb_build_array(fresh->'singleton')||(fresh->'members')) LOOP
 INSERT INTO finance_group_members VALUES(revision,idx,CASE WHEN idx=0 THEN 'singleton' ELSE 'member' END,member->>'documentId',member->>'portionId',member->>'observationId',member);idx:=idx+1;END LOOP;
 result:=jsonb_build_object('caseId',id,'revisionId',revision,'version',version,'state',state,'replayed',false,'financialUseSupported',false);
 INSERT INTO finance_group_requests VALUES(p_request,p_action,p_actor,p_input,finance_document_hash(p_input),result,now());RETURN result;
END $$;
CREATE OR REPLACE FUNCTION finance_group_list(p_subject text,p_case text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE records jsonb:='[]';items jsonb;v record;c record;n integer:=0;has_more boolean:=false;count_cases integer;
BEGIN
 SELECT count(*) INTO count_cases FROM finance_group_cases WHERE subject_id=p_subject AND (p_case IS NULL OR case_id=p_case);has_more:=count_cases>100;
 FOR c IN SELECT * FROM finance_group_cases WHERE subject_id=p_subject AND (p_case IS NULL OR case_id=p_case) ORDER BY created_at DESC,case_id LIMIT 100 LOOP
 items:='[]';n:=0;FOR v IN SELECT * FROM finance_group_revisions WHERE case_id=c.case_id ORDER BY version DESC LOOP
 PERFORM finance_group_assert_request(v.request_id);n:=n+1;
 IF n<=100 AND (p_case IS NOT NULL OR n=1) THEN items:=items||jsonb_build_array(jsonb_build_object('caseId',v.case_id,'revisionId',v.revision_id,'version',v.version,'state',v.state,'financialUseSupported',false,'previousRevisionId',v.previous_revision_id,'draft',v.input_json->'draft','preview',v.preview_json,'withdrawalReason',v.withdrawal_reason,'createdAt',v.created_at));END IF;
 END LOOP;IF p_case IS NOT NULL AND n>100 THEN has_more:=true;END IF;records:=records||items;END LOOP;
 RETURN jsonb_build_object('records',records,'hasMore',has_more);
EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION 'Group archived records unavailable' USING ERRCODE='55000';END $$;
CREATE OR REPLACE FUNCTION finance_assert_group_definitions(p_schema text) RETURNS jsonb LANGUAGE sql AS $$ SELECT finance_assert_same_definitions(p_schema) $$;

CREATE OR REPLACE FUNCTION finance_assert_same_definitions(p_schema text) RETURNS jsonb LANGUAGE plpgsql AS $de1b$
DECLARE expected jsonb := '{"version":"de1b-group-installation-v1","postgresMajor":17,"functions":[{"cost":"100","kind":"f","name":"finance_assert_group_definitions","rows":"0","binary":null,"config":null,"result":"jsonb","source":" SELECT finance_assert_same_definitions(p_schema) ","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p_schema text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_group_agreement","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE request text;v finance_group_revisions%ROWTYPE;\nBEGIN\n IF TG_TABLE_NAME=''finance_group_cases'' THEN\n SELECT * INTO STRICT v FROM finance_group_revisions WHERE case_id=NEW.case_id AND version=1;\n IF v.request_id IS DISTINCT FROM NEW.created_request_id OR v.actor_user_id IS DISTINCT FROM NEW.actor_user_id OR v.input_json#>>''{draft,subjectId}'' IS DISTINCT FROM NEW.subject_id OR finance_group_key(v.input_json->''draft'') IS DISTINCT FROM NEW.group_key THEN RAISE EXCEPTION ''Group new root agreement mismatch'' USING ERRCODE=''23514'';END IF;request:=NEW.created_request_id;\n ELSIF TG_TABLE_NAME=''finance_group_members'' THEN SELECT request_id INTO STRICT request FROM finance_group_revisions WHERE revision_id=NEW.revision_id;\n ELSE request:=NEW.request_id;END IF;\n PERFORM finance_group_assert_request(request);RETURN NULL;\nEXCEPTION WHEN no_data_found THEN RAISE EXCEPTION ''Group orphan record'' USING ERRCODE=''23514'';END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_group_assert_request","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE q finance_group_requests%ROWTYPE;v finance_group_revisions%ROWTYPE;c finance_group_cases%ROWTYPE;e finance_group_evidence%ROWTYPE;prior finance_group_revisions%ROWTYPE;\n expected jsonb;actual jsonb;fresh jsonb;input jsonb;member jsonb;idx integer:=0;\nBEGIN\n SELECT * INTO STRICT q FROM finance_group_requests WHERE request_id=p_request;\n IF q.payload_hash IS DISTINCT FROM finance_document_hash(q.payload_json) OR NOT finance_supply_id(to_jsonb(q.actor_user_id)) OR NOT finance_supply_id(to_jsonb(q.request_id)) OR q.payload_json->>''requestId'' IS DISTINCT FROM q.request_id THEN RAISE EXCEPTION ''Group request integrity mismatch'' USING ERRCODE=''23514'';END IF;\n IF q.action=''evidence'' THEN\n SELECT * INTO STRICT e FROM finance_group_evidence WHERE request_id=q.request_id;\n IF e.payload_json IS DISTINCT FROM q.payload_json OR e.manifest_hash IS DISTINCT FROM finance_document_hash(e.payload_json) OR e.actor_user_id IS DISTINCT FROM q.actor_user_id\n OR e.subject_id IS DISTINCT FROM e.payload_json->>''subjectId'' OR e.document_id IS DISTINCT FROM e.payload_json->>''documentId'' OR e.document_hash IS DISTINCT FROM e.payload_json->>''evidenceHash''\n OR e.verification_level<>''human_review'' OR finance_group_evidence_valid(e.payload_json) IS DISTINCT FROM true OR finance_same_document(e.document_id,e.subject_id,e.document_hash) IS NULL THEN RAISE EXCEPTION ''Group evidence archive mismatch'' USING ERRCODE=''23514'';END IF;\n expected:=jsonb_build_object(''manifestId'',e.manifest_id,''manifestHash'',e.manifest_hash,''verificationLevel'',''human_review'',''replayed'',false);\n ELSE\n SELECT * INTO STRICT v FROM finance_group_revisions WHERE request_id=q.request_id;SELECT * INTO STRICT c FROM finance_group_cases WHERE case_id=v.case_id;\n IF v.actor_user_id IS DISTINCT FROM q.actor_user_id OR v.proof_hash IS DISTINCT FROM finance_document_hash(jsonb_build_object(''input'',v.input_json,''preview'',v.preview_json,''basis'',v.basis_json))\n OR c.subject_id IS DISTINCT FROM v.input_json#>>''{draft,subjectId}'' OR c.group_key IS DISTINCT FROM finance_group_key(v.input_json->''draft'') OR finance_group_input(v.input_json) IS DISTINCT FROM true\n OR v.preview_json->''financialUseSupported'' IS DISTINCT FROM ''false''::jsonb OR v.preview_json->''canVerify'' IS DISTINCT FROM ''true''::jsonb OR v.preview_json->''issues'' IS DISTINCT FROM ''[]''::jsonb\n THEN RAISE EXCEPTION ''Group archive integrity mismatch'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO prior FROM finance_group_revisions WHERE case_id=v.case_id AND version=v.version-1;\n IF (v.version=1 AND (c.created_request_id IS DISTINCT FROM v.request_id OR c.actor_user_id IS DISTINCT FROM v.actor_user_id OR v.previous_revision_id IS NOT NULL))\n OR (v.version>1 AND (prior.revision_id IS NULL OR prior.revision_id IS DISTINCT FROM v.previous_revision_id)) THEN RAISE EXCEPTION ''Group archive chain mismatch'' USING ERRCODE=''23514'';END IF;\n IF q.action=''verify'' THEN\n IF v.state<>''verified_group'' OR finance_group_input(q.payload_json,true) IS DISTINCT FROM true OR q.payload_json-ARRAY[''expectedPreviewHash'',''requestId''] IS DISTINCT FROM v.input_json\n OR q.payload_json->>''expectedPreviewHash'' IS DISTINCT FROM v.preview_json->>''previewHash''\n OR (v.input_json->>''expectedVersion'')::integer<>v.version-1 OR v.input_json->>''expectedRevisionId'' IS DISTINCT FROM prior.revision_id\n OR v.input_json->>''caseId'' IS DISTINCT FROM (CASE WHEN v.version=1 THEN NULL ELSE v.case_id END) THEN RAISE EXCEPTION ''Group verified request mismatch'' USING ERRCODE=''23514'';END IF;\n IF v.apply_xid=pg_current_xact_id_if_assigned() THEN\n fresh:=finance_group_candidate(v.input_json,v.case_id);IF fresh->>''canVerify'' IS DISTINCT FROM ''true'' OR fresh-''_basis'' IS DISTINCT FROM v.preview_json OR fresh->''_basis'' IS DISTINCT FROM v.basis_json THEN RAISE EXCEPTION ''Group current proof changed before commit'' USING ERRCODE=''23514'';END IF;END IF;\n ELSE\n IF v.state<>''withdrawn'' OR prior.state<>''verified_group'' OR v.input_json IS DISTINCT FROM prior.input_json OR v.preview_json IS DISTINCT FROM prior.preview_json OR v.basis_json IS DISTINCT FROM prior.basis_json\n OR q.payload_json->>''caseId'' IS DISTINCT FROM v.case_id OR q.payload_json->>''subjectId'' IS DISTINCT FROM c.subject_id OR q.payload_json->>''expectedRevisionId'' IS DISTINCT FROM prior.revision_id\n OR (q.payload_json->>''expectedVersion'')::integer<>prior.version OR q.payload_json->>''reason'' IS DISTINCT FROM v.withdrawal_reason THEN RAISE EXCEPTION ''Group withdrawal request mismatch'' USING ERRCODE=''23514'';END IF;END IF;\n SELECT COALESCE(jsonb_agg(jsonb_build_object(''memberNo'',member_no,''role'',role,''documentId'',document_id,''portionId'',portion_id,''observationId'',observation_id,''summary'',summary_json) ORDER BY member_no),''[]'') INTO actual FROM finance_group_members WHERE revision_id=v.revision_id;\n expected:=''[]'';FOR member IN SELECT value FROM jsonb_array_elements(jsonb_build_array(v.preview_json->''singleton'')||(v.preview_json->''members'')) LOOP\n IF NOT EXISTS(SELECT 1 FROM finance_document_portions p JOIN finance_document_observations o USING(document_id) WHERE p.portion_id=member->>''portionId'' AND p.locator=''whole'' AND o.observation_id=member->>''observationId'' AND o.subject_id=c.subject_id)\n THEN RAISE EXCEPTION ''Group archived whole reference missing'' USING ERRCODE=''23514'';END IF;\n expected:=expected||jsonb_build_array(jsonb_build_object(''memberNo'',idx,''role'',CASE WHEN idx=0 THEN ''singleton'' ELSE ''member'' END,''documentId'',member->>''documentId'',''portionId'',member->>''portionId'',''observationId'',member->>''observationId'',''summary'',member));idx:=idx+1;\n END LOOP;\n IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION ''Group exact member set mismatch'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO STRICT e FROM finance_group_evidence WHERE manifest_id=v.input_json#>>''{draft,evidenceManifestId}'';PERFORM finance_group_assert_request(e.request_id);\n IF v.basis_json#>>''{evidence,manifestHash}'' IS DISTINCT FROM e.manifest_hash OR e.subject_id<>c.subject_id THEN RAISE EXCEPTION ''Group evidence reference mismatch'' USING ERRCODE=''23514'';END IF;\n expected:=jsonb_build_object(''caseId'',v.case_id,''revisionId'',v.revision_id,''version'',v.version,''state'',v.state,''replayed'',false,''financialUseSupported'',false);\n END IF;\n IF q.result_json IS DISTINCT FROM expected THEN RAISE EXCEPTION ''Group result mismatch'' USING ERRCODE=''23514'';END IF;\nEXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION ''Group complete request missing'' USING ERRCODE=''23514'';END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_request text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_group_candidate","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE d jsonb;one jsonb;side jsonb;ref jsonb;ev finance_group_evidence%ROWTYPE;last_row finance_group_revisions%ROWTYPE;root_row finance_group_cases%ROWTYPE;\n issues jsonb:=''[]'';members jsonb:=''[]'';sides jsonb:=''[]'';times jsonb:=''[]'';relations jsonb;basis jsonb;result jsonb;currency jsonb;region jsonb;sum_supply numeric:=0;sum_tax numeric:=0;sum_total numeric:=0;\n all_refs jsonb;other record;region2 jsonb;reference_doc jsonb;\nBEGIN\n IF finance_group_input(p_input) IS DISTINCT FROM true THEN RAISE EXCEPTION ''Invalid whole group input'' USING ERRCODE=''22023'';END IF;\n d:=p_input->''draft'';one:=finance_same_side(d,d->''singleton'');issues:=issues||(one->''issues'');times:=times||(one->''times'');all_refs:=jsonb_build_array(d->''singleton'')||(d->''members'');\n FOR ref IN SELECT value FROM jsonb_array_elements(d->''members'') LOOP\n side:=finance_same_side(d,ref);issues:=issues||(side->''issues'');times:=times||(side->''times'');members:=members||jsonb_build_array(side->''summary'');sides:=sides||jsonb_build_array(side);\n IF side->''summary'' IS NULL OR side->''summary''=''null''::jsonb OR side#>>''{summary,direction}'' IS DISTINCT FROM one#>>''{summary,direction}'' OR side->>''counterparty'' IS DISTINCT FROM one->>''counterparty'' THEN issues:=issues||finance_document_issue(''group_counterparty_mismatch'',''기준과 구성원의 회사·방향·거래처를 확인하세요.'');END IF;\n IF COALESCE((side#>>''{summary,supply}'')::numeric,0)<0 OR COALESCE((side#>>''{summary,tax}'')::numeric,0)<0 OR COALESCE((side#>>''{summary,total}'')::numeric,0)<=0 THEN issues:=issues||finance_document_issue(''group_amount_unsupported'',''양수 전체 문서만 지원합니다. 취소액을 상계하지 않습니다.'');END IF;\n sum_supply:=sum_supply+COALESCE((side#>>''{summary,supply}'')::numeric,0);sum_tax:=sum_tax+COALESCE((side#>>''{summary,tax}'')::numeric,0);sum_total:=sum_total+COALESCE((side#>>''{summary,total}'')::numeric,0);\n END LOOP;\n IF sum_supply IS DISTINCT FROM (one#>>''{summary,supply}'')::numeric OR sum_tax IS DISTINCT FROM (one#>>''{summary,tax}'')::numeric OR sum_total IS DISTINCT FROM (one#>>''{summary,total}'')::numeric\n OR sum_total<>sum_supply+sum_tax OR sum_total<=0 OR sum_total>9007199254740991 THEN issues:=issues||finance_document_issue(''group_amount_mismatch'',''기준 전체와 구성원 전체의 공급가액·세액·합계를 각각 맞추세요.'');END IF;\n SELECT * INTO ev FROM finance_group_evidence WHERE manifest_id=d->>''evidenceManifestId'';\n IF NOT FOUND OR ev.subject_id IS DISTINCT FROM d->>''subjectId'' THEN issues:=issues||finance_document_issue(''group_evidence_unavailable'',''같은 회사의 보관 원문 위치 근거를 선택하세요.'');\n ELSE\n PERFORM finance_group_assert_request(ev.request_id);reference_doc:=finance_same_document(ev.document_id,ev.subject_id,ev.document_hash);\n IF reference_doc IS NULL THEN issues:=issues||finance_document_issue(''group_evidence_unavailable'',''보관 원문 근거를 확인할 수 없습니다.'');END IF;\n FOR ref IN SELECT value FROM jsonb_array_elements(all_refs) LOOP\n IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ev.payload_json->''regions'') z CROSS JOIN LATERAL jsonb_array_elements(z->''wholeRefs'') w WHERE w=ref AND (ref=d->''singleton'' OR z->>''role''=''detail''))\n THEN issues:=issues||finance_document_issue(''group_coverage_missing'',''기준 문서의 원문 위치와 각 구성원의 세부 원문 위치가 필요합니다.'');END IF;\n IF (SELECT count(*) FROM jsonb_array_elements(d->''currencyEvidence'') c WHERE c->>''documentId''=ref->>''documentId'')<>1 THEN issues:=issues||finance_document_issue(''group_currency_unavailable'',''각 문서의 통화 원문 근거를 지정하세요.'');\n ELSE\n SELECT c INTO currency FROM jsonb_array_elements(d->''currencyEvidence'') c WHERE c->>''documentId''=ref->>''documentId'';\n IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ev.payload_json->''regions'') z CROSS JOIN LATERAL jsonb_array_elements(z->''wholeRefs'') w WHERE z->>''regionId''=currency->>''manifestRegionId'' AND w=ref)\n THEN issues:=issues||finance_document_issue(''group_currency_unavailable'',''통화 표시가 있는 실제 원문 영역과 문서를 결속하세요.'');END IF;END IF;\n END LOOP;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(ev.payload_json->''regions'') z CROSS JOIN LATERAL jsonb_array_elements(z->''wholeRefs'') w WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(all_refs) a WHERE a=w)) THEN issues:=issues||finance_document_issue(''group_coverage_extra'',''다른 문서가 섞인 원문 대응 범위를 다시 선택하세요.'');END IF;\n FOR region IN SELECT value FROM jsonb_array_elements(ev.payload_json->''regions'') WHERE value->>''role''=''detail'' LOOP\n IF (SELECT count(DISTINCT w->>''portionId'') FROM jsonb_array_elements(region->''wholeRefs'') w WHERE w->>''portionId''<>d#>>''{singleton,portionId}'')>1 THEN issues:=issues||finance_document_issue(''group_detail_overlap'',''같은 세부 원문 영역을 여러 구성원에 중복 배정할 수 없습니다.'');END IF;\n FOR region2 IN SELECT value FROM jsonb_array_elements(ev.payload_json->''regions'') WHERE value->>''role''=''detail'' AND value->>''regionId''>region->>''regionId'' LOOP\n IF region->''pageNumber''=region2->''pageNumber'' AND (region#>>''{rect,x}'')::numeric<(region2#>>''{rect,x}'')::numeric+(region2#>>''{rect,width}'')::numeric AND (region2#>>''{rect,x}'')::numeric<(region#>>''{rect,x}'')::numeric+(region#>>''{rect,width}'')::numeric\n AND (region#>>''{rect,y}'')::numeric<(region2#>>''{rect,y}'')::numeric+(region2#>>''{rect,height}'')::numeric AND (region2#>>''{rect,y}'')::numeric<(region#>>''{rect,y}'')::numeric+(region#>>''{rect,height}'')::numeric\n AND EXISTS(SELECT 1 FROM jsonb_array_elements(region->''wholeRefs'') a CROSS JOIN jsonb_array_elements(region2->''wholeRefs'') b WHERE a->>''portionId''<>d#>>''{singleton,portionId}'' AND b->>''portionId''<>d#>>''{singleton,portionId}'' AND a->>''portionId''<>b->>''portionId'')\n THEN issues:=issues||finance_document_issue(''group_detail_overlap'',''서로 다른 구성원의 세부 원문 영역이 겹칩니다. 공통 제목은 context로 구분하세요.'');END IF;\n END LOOP;END LOOP;\n END IF;\n IF p_ignore_case IS NULL THEN\n IF p_input->>''caseId'' IS NOT NULL THEN\n SELECT * INTO root_row FROM finance_group_cases WHERE case_id=p_input->>''caseId'';SELECT * INTO last_row FROM finance_group_revisions WHERE case_id=p_input->>''caseId'' ORDER BY version DESC LIMIT 1;\n IF root_row.subject_id IS DISTINCT FROM d->>''subjectId'' OR root_row.group_key IS DISTINCT FROM finance_group_key(d) OR last_row.version IS DISTINCT FROM (p_input->>''expectedVersion'')::integer OR last_row.revision_id IS DISTINCT FROM p_input->>''expectedRevisionId'' THEN issues:=issues||finance_document_issue(''group_revision_stale'',''같은 문서 집합의 최신판을 다시 선택하세요.'');END IF;\n ELSIF EXISTS(SELECT 1 FROM finance_group_cases WHERE subject_id=d->>''subjectId'' AND group_key=finance_group_key(d)) THEN issues:=issues||finance_document_issue(''group_case_exists'',''이미 등록된 정확 집합의 최신판을 선택하세요.'');END IF;END IF;\n relations:=finance_group_relations(d,true);issues:=issues||(relations->''issues'');\n FOR other IN SELECT v.* FROM finance_group_revisions v JOIN finance_group_cases c USING(case_id) WHERE c.subject_id=d->>''subjectId'' AND v.state=''verified_group'' AND c.case_id IS DISTINCT FROM COALESCE(p_input->>''